SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Home hero person photo (mockup 2026-11-04 rev. 2) — generated by tools/content/build-hero-photo.php
-- Illustrative stock photo (Unsplash License), labelled on the page. Only replaces the 044 stock photo;
-- a hero photo already changed in the CMS is left alone.

-- media: hero-executive
-- alt: ภาพประกอบ ผู้บริหารธุรกิจในชุดสูทสีกรมท่า
INSERT INTO media (path, mime, width, height, alt, title, sizes, bytes, created_at, updated_at)
SELECT '/assets/images/stock/hero-executive.webp', 'image/webp', 1200, 1484, CONVERT(X'E0B8A0E0B8B2E0B89EE0B89BE0B8A3E0B8B0E0B881E0B8ADE0B89A20E0B89CE0B8B9E0B989E0B89AE0B8A3E0B8B4E0B8ABE0B8B2E0B8A3E0B898E0B8B8E0B8A3E0B881E0B8B4E0B888E0B983E0B899E0B88AE0B8B8E0B894E0B8AAE0B8B9E0B897E0B8AAE0B8B5E0B881E0B8A3E0B8A1E0B897E0B988E0B8B2' USING utf8mb4), 'hero-executive', '{"webp":"/assets/images/stock/hero-executive.webp","480":"/assets/images/stock/hero-executive-480.webp","768":"/assets/images/stock/hero-executive-768.webp","1200":"/assets/images/stock/hero-executive.webp"}', 74026, NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM media WHERE path = '/assets/images/stock/hero-executive.webp' AND deleted_at IS NULL);

-- /  ·  alt: ภาพประกอบ ผู้บริหารธุรกิจในชุดสูทสีกรมท่า
UPDATE pages SET blocks = JSON_SET(blocks, '$[0].data.person', JSON_EXTRACT(CONVERT(X'' USING utf8mb4), '$')), updated_at = NOW()
WHERE path = CONVERT(X'2F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'th' AND deleted_at IS NULL
  AND JSON_UNQUOTE(JSON_EXTRACT(blocks, '$[0].type')) = 'hero'
  AND JSON_UNQUOTE(JSON_EXTRACT(blocks, '$[0].data.person.src')) = '/assets/images/stock/hero-consultant.webp';

